using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using Cysharp.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Nox.CCK.Utils;
using Nox.Network.WebSocket;
using Nox.SDK.Control;

namespace api.nox.control {
	public class Client : IClient {
		private readonly Server    _server;
		private          TcpClient _client;

		internal Client(TcpClient client, Server server) {
			_client = client;
			_server = server;
		}

		public EndPoint GetEndPoint()
			=> _client.Client.RemoteEndPoint;

		public bool IsConnected()
			=> _client is { Connected: true };

		public async UniTask Close() {
			if (!IsConnected()) return;

			try {
				_client.Close();
				_client = null;
				await UniTask.Yield();
			} catch (Exception ex) {
				Logger.LogError($"Error closing connection to client {GetEndPoint()}: {ex.Message}");
			}
		}

		public IServer GetServer()
			=> _server;

		public async UniTask Send(string ev, params object[] args) {
			if (!IsConnected()) return;

			var payload = new JObject {
				["event"] = ev,
				["args"]  = new JArray(args)
			};

			var str    = payload.ToString(Formatting.None);
			var buffer = Encoding.UTF8.GetBytes(str);



		}
	}
}

using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using Cysharp.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Nox.CCK.Utils;
using Nox.SDK.Control;

namespace api.nox.control {
	public class Client : IClient {
		private readonly Server _server;
		private TcpClient _client;
		private NetworkStream _stream;

		internal Client(TcpClient client, Server server) {
			_client = client;
			_server = server;
			_stream = _client.GetStream();
		}

		public EndPoint GetEndPoint() => _client?.Client?.RemoteEndPoint;

		public bool IsConnected() => _client is { Connected: true };

		public async UniTask Close() {
			if (!IsConnected()) return;

			try {
				_stream?.Close();
				_client?.Close();
				_client = null;
				_stream = null;
				await UniTask.Yield();
			} catch (Exception ex) {
				Logger.LogError($"Error closing connection to client {GetEndPoint()}: {ex.Message}");
			}
		}

		public IServer GetServer() => _server;

		public async UniTask Send(string ev, params object[] args) {
			if (!IsConnected()) return;

			try {
				var payload = new JObject {
					["event"] = ev,
					["args"] = new JArray(args)
				};

				var str = payload.ToString(Formatting.None);
				var buffer = Encoding.UTF8.GetBytes(str + "\n");

				await _stream.WriteAsync(buffer, 0, buffer.Length);
			} catch (Exception ex) {
				Logger.LogError($"Error sending data to client {GetEndPoint()}: {ex.Message}");
			}
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using Cysharp.Threading.Tasks;
using Nox.CCK.Mods;
using Nox.CCK.Mods.Events;
using Nox.CCK.Mods.Metadata;
using Nox.CCK.Utils;
using Nox.ModLoader.Cores.Assets;
using Nox.ModLoader.EntryPoints;

namespace Nox.ModLoader.Mods {
	public abstract class Mod : IMod {
		internal CoreAPI            CoreAPI;
		internal IAssetAPI          AssetAPI;
		internal Typing.ModMetadata Metadata;
		public   Profiler           Profiler;

		public abstract AppDomain GetAppDomain();

		public abstract Assembly[] GetAssemblies();

		public Profile[] GetProfiler()
			=> Profiler.Profiles.ToArray();

		public ModMetadata GetMetadata()
			=> Metadata;

		internal Mod() {
			CoreAPI  = new CoreAPI(this);
			Profiler = new Profiler();
		}

		#region Data Storage

		public T GetData<T>(string key, T defaultValue = default)
			=> HasData<T>(key) ? (T)GetDatas()[key] : defaultValue;

		public bool SetData<T>(string key, T value) {
			GetDatas()[key] = value;
			return true;
		}

		public bool HasData<T>(string key)
			=> GetDatas().ContainsKey(key);

		public Dictionary<string, object> GetDatas()
			=> Metadata.InternalData;

		#endregion

		#region Entrypoints Instances

		private EntryPoint[] _entryPoints = Array.Empty<EntryPoint>();

		public T GetInstance<T>() {
			T instance = default;

			foreach (var entry in _entryPoints) {
				instance = entry.GetInstance<T>();
				if (instance != null) break;
			}

			return instance;
		}

		public T[] GetInstances<T>() {
			var instances = new List<T>();

			foreach (var entry in _entryPoints)
				instances.AddRange(entry.GetInstances<T>());

			return instances.ToArray();
		}

		public EntryPoint GetEntry(string name)
			=> _entryPoints.FirstOrDefault(e => e.Name == name);

		#endregion

		public virtual bool IsLoaded()
			=> true;

		public bool HasUpdate      = false;
		public bool HasFixedUpdate = false;
		public bool HasLateUpdate  = false;

		public virtual UniTask<bool> Load() {
			CoreAPI.EventAPI.Emit(new ModEventContext("mod_loaded", this));

			_entryPoints = Metadata
				.GetEntryPoints()
				.GetAll()
				.Keys
				.Select(entry => new EntryPoint(this, entry))
				.ToArray();

			HasUpdate = _entryPoints.Any(e => e.HasUpdate);
			HasFixedUpdate = _entryPoints.Any(e => e.HasFixedUpdate);
			HasLateUpdate = _entryPoints.Any(e => e.HasLateUpdate);

			return UniTask.FromResult(true);
		}

		public virtual async UniTask<bool> Unload() {
			Logger.LogDebug($"Unloading {Metadata.GetId()}@{Metadata.GetVersion()}");

			// if not disabled, disable
			foreach (var entry in _entryPoints)
				entry.Disable();

			// send pre-dispose and dispose
			await PreDispose();
			await Dispose();

			// clear all states

			foreach (var entry in _entryPoints)
				entry.Dispose();

			_entryPoints = Array.Empty<EntryPoint>();
			CoreAPI.EventAPI.Emit(new ModEventContext("mod_unloaded", this));
			return true;
		}

		public async UniTask Initialize() {
			Profiler.Set("initialize", Profiler.At.Start, DateTime.UtcNow);
			var promises = new UniTask[_entryPoints.Length];
			for (var i = 0; i < _entryPoints.Length; i++)
				promises[i] = _entryPoints[i].OnInitialize();
			await UniTask.WhenAll(promises);
			Profiler.Set("initialized", Profiler.At.Start, DateTime.UtcNow);
		}

		public async UniTask PostInitialize() {
			Profiler.Set("post_initialize", Profiler.At.Start, DateTime.UtcNow);
			var promises = new UniTask[_entryPoints.Length];
			for (var i = 0; i < _entryPoints.Length; i++)
				promises[i] = _entryPoints[i].OnPostInitialize();
			await UniTask.WhenAll(promises);
			Profiler.Set("post_initialized", Profiler.At.Start, DateTime.UtcNow);
		}

		public async UniTask PreDispose() {
			Profiler.Set("pre_dispose", Profiler.At.Start, DateTime.UtcNow);
			var promises = new UniTask[_entryPoints.Length];
			for (var i = 0; i < _entryPoints.Length; i++)
				promises[i] = _entryPoints[i].OnPreDispose();
			await UniTask.WhenAll(promises);
			Profiler.Set("pre_disposed", Profiler.At.Start, DateTime.UtcNow);
		}

		public void Update() {
			if (!HasUpdate) return;
			Profiler.Set("update", Profiler.At.Start, DateTime.UtcNow);
			foreach (var entry in _entryPoints)
				entry.OnUpdate();
			Profiler.Set("updated", Profiler.At.Start, DateTime.UtcNow);
		}

		public void FixedUpdate() {
			if (!HasFixedUpdate) return;
			Profiler.Set("fixed_update", Profiler.At.Start, DateTime.UtcNow);
			foreach (var entry in _entryPoints)
				entry.OnFixedUpdate();
			Profiler.Set("fixed_updated", Profiler.At.Start, DateTime.UtcNow);
		}

		public void LateUpdate() {
			if (!HasLateUpdate) return;
			Profiler.Set("late_update", Profiler.At.Start, DateTime.UtcNow);
			foreach (var entry in _entryPoints)
				entry.OnLateUpdate();
			Profiler.Set("late_updated", Profiler.At.Start, DateTime.UtcNow);
		}

		public async UniTask Dispose() {
			Profiler.Set("dispose", Profiler.At.Start, DateTime.UtcNow);
			var promises = new UniTask[_entryPoints.Length];
			for (var i = 0; i < _entryPoints.Length; i++)
				promises[i] = _entryPoints[i].OnDispose();
			await UniTask.WhenAll(promises);
			Profiler.Set("disposed", Profiler.At.Start, DateTime.UtcNow);
		}

		public override string ToString()
			=> $"{GetType().Name}[id={Metadata.GetId()}, version={Metadata.GetVersion()}]";
	}

	public enum InitializerState : byte {
		None            = 0,
		Initialized     = 1,
		PostInitialized = 2,

		PreDisposed = 4,
		Disposed    = 8,

		Ready = PostInitialized & Disposed,
		Done  = Initialized     & Disposed
	}

	public enum ExecutionEventStatus : byte {
		None    = 0,
		Pre     = 1,
		Start   = 2,
		Success = 3,
		Error   = 4,
	}


	public class ModEventContext : EventContext {
		private readonly object[] _data;
		private readonly string   _eventName;

		public ModEventContext(string eventName, params object[] data) {
			_eventName = eventName;
			_data      = data;
		}

		public object[] Data
			=> _data;

		public string Destination
			=> null;

		public string EventName
			=> _eventName;

		public EventEntryFlags Channel
			=> EventEntryFlags.Client | EventEntryFlags.Main | EventEntryFlags.Editor;

		public Action<object[]> Callback { get; }
	}
}

using System;
using System.Collections.Generic;
using System.Reflection;
using Cysharp.Threading.Tasks;
using Nox.CCK.Mods;
using Nox.CCK.Mods.Events;
using Nox.CCK.Mods.Metadata;
using Nox.CCK.Utils;
using Nox.ModLoader.Cores.Assets;
using Nox.ModLoader.EntryPoints;

namespace Nox.ModLoader.Mods {
	public abstract class Mod : IMod {
		internal CoreAPI            CoreAPI;
		internal IAssetAPI          AssetAPI;
		internal Typing.ModMetadata Metadata;
		public   Profiler           Profiler;

		public abstract AppDomain GetAppDomain();

		public abstract Assembly[] GetAssemblies();

		public IEnumerable<Profile> GetProfiler()
			=> Profiler.GetAllProfiles();

		public ModMetadata GetMetadata()
			=> Metadata;

		internal Mod() {
			CoreAPI  = new CoreAPI(this);
			Profiler = new Profiler();
		}

		#region Data Storage

		public T GetData<T>(string key, T defaultValue = default)
			=> HasData<T>(key) ? (T)GetDatas()[key] : defaultValue;

		public bool SetData<T>(string key, T value) {
			GetDatas()[key] = value;
			return true;
		}

		public bool HasData<T>(string key)
			=> GetDatas().ContainsKey(key);

		public Dictionary<string, object> GetDatas()
			=> Metadata.InternalData;

		#endregion

		#region Entrypoints Instances

		private EntryPoint[] _entryPoints = Array.Empty<EntryPoint>();

		public T GetInstance<T>() {
			T instance = default;

			foreach (var entry in _entryPoints) {
				instance = entry.GetInstance<T>();
				if (instance != null) break;
			}

			return instance;
		}

		public T[] GetInstances<T>() {
			var instances = new List<T>();

			foreach (var entry in _entryPoints)
				instances.AddRange(entry.GetInstances<T>());

			return instances.ToArray();
		}

		public EntryPoint GetEntry(string name) {
			foreach (var entry in _entryPoints)
				if (entry.Name == name)
					return entry;
			return null;
		}

		#endregion

		public virtual bool IsLoaded()
			=> true;

		public bool HasUpdate;
		public bool HasFixedUpdate;
		public bool HasLateUpdate;

		public virtual UniTask<bool> Load() {
			CoreAPI.EventAPI.Emit(new ModEventContext("mod_loaded", this));

			var entryPointKeys = Metadata.GetEntryPoints().GetAll().Keys;
			_entryPoints = new EntryPoint[entryPointKeys.Count];
			var index = 0;
			foreach (var entry in entryPointKeys)
				_entryPoints[index++] = new EntryPoint(this, entry);

			HasUpdate = false;
			HasFixedUpdate = false;
			HasLateUpdate = false;

			foreach (var entry in _entryPoints) {
				if (entry.HasUpdate) HasUpdate = true;
				if (entry.HasFixedUpdate) HasFixedUpdate = true;
				if (entry.HasLateUpdate) HasLateUpdate = true;
			}

			return UniTask.FromResult(true);
		}

		public virtual async UniTask<bool> Unload() {
			Logger.LogDebug($"Unloading {Metadata.GetId()}@{Metadata.GetVersion()}");

			// if not disabled, disable
			foreach (var entry in _entryPoints)
				entry.Disable();

			// send pre-dispose and dispose
			await PreDispose();
			await Dispose();

			// clear all states

			foreach (var entry in _entryPoints)
				entry.Dispose();

			_entryPoints = Array.Empty<EntryPoint>();
			CoreAPI.EventAPI.Emit(new ModEventContext("mod_unloaded", this));
			return true;
		}

		public async UniTask Initialize() {
			Profiler.Set("initialize", Profiler.At.Start, DateTime.UtcNow);
			var promises = new UniTask[_entryPoints.Length];
			for (var i = 0; i < _entryPoints.Length; i++)
				promises[i] = _entryPoints[i].OnInitialize();
			await UniTask.WhenAll(promises);
			Profiler.Set("initialized", Profiler.At.Start, DateTime.UtcNow);
		}

		public async UniTask PostInitialize() {
			Profiler.Set("post_initialize", Profiler.At.Start, DateTime.UtcNow);
			var promises = new UniTask[_entryPoints.Length];
			for (var i = 0; i < _entryPoints.Length; i++)
				promises[i] = _entryPoints[i].OnPostInitialize();
			await UniTask.WhenAll(promises);
			Profiler.Set("post_initialized", Profiler.At.Start, DateTime.UtcNow);
		}

		public async UniTask PreDispose() {
			Profiler.Set("pre_dispose", Profiler.At.Start, DateTime.UtcNow);
			var promises = new UniTask[_entryPoints.Length];
			for (var i = 0; i < _entryPoints.Length; i++)
				promises[i] = _entryPoints[i].OnPreDispose();
			await UniTask.WhenAll(promises);
			Profiler.Set("pre_disposed", Profiler.At.Start, DateTime.UtcNow);
		}

		public void Update() {
			if (!HasUpdate) return;
			Profiler.Set("update", Profiler.At.Start, DateTime.UtcNow);
			foreach (var entry in _entryPoints)
				entry.OnUpdate();
			Profiler.Set("updated", Profiler.At.Start, DateTime.UtcNow);
		}

		public void FixedUpdate() {
			if (!HasFixedUpdate) return;
			Profiler.Set("fixed_update", Profiler.At.Start, DateTime.UtcNow);
			foreach (var entry in _entryPoints)
				entry.OnFixedUpdate();
			Profiler.Set("fixed_updated", Profiler.At.Start, DateTime.UtcNow);
		}

		public void LateUpdate() {
			if (!HasLateUpdate) return;
			Profiler.Set("late_update", Profiler.At.Start, DateTime.UtcNow);
			foreach (var entry in _entryPoints)
				entry.OnLateUpdate();
			Profiler.Set("late_updated", Profiler.At.Start, DateTime.UtcNow);
		}

		public async UniTask Dispose() {
			Profiler.Set("dispose", Profiler.At.Start, DateTime.UtcNow);
			var promises = new UniTask[_entryPoints.Length];
			for (var i = 0; i < _entryPoints.Length; i++)
				promises[i] = _entryPoints[i].OnDispose();
			await UniTask.WhenAll(promises);
			Profiler.Set("disposed", Profiler.At.Start, DateTime.UtcNow);
		}

		public override string ToString()
			=> $"{GetType().Name}[id={Metadata.GetId()}, version={Metadata.GetVersion()}]";
	}

	public enum InitializerState : byte {
		None            = 0,
		Initialized     = 1,
		PostInitialized = 2,

		PreDisposed = 4,
		Disposed    = 8,

		Ready = PostInitialized & Disposed,
		Done  = Initialized     & Disposed
	}

	public enum ExecutionEventStatus : byte {
		None    = 0,
		Pre     = 1,
		Start   = 2,
		Success = 3,
		Error   = 4,
	}


	public class ModEventContext : EventContext {
		private readonly object[] _data;
		private readonly string   _eventName;

		public ModEventContext(string eventName, params object[] data) {
			_eventName = eventName;
			_data      = data;
		}

		public object[] Data
			=> _data;

		public string Destination
			=> null;

		public string EventName
			=> _eventName;

		public EventEntryFlags Channel
			=> EventEntryFlags.Client | EventEntryFlags.Main | EventEntryFlags.Editor;

		public Action<object[]> Callback { get; }
	}
}

using Nox.CCK.Mods.Cores;
using Nox.CCK.Mods.Initializers;

namespace api.nox.websocket {
	public class Main : IMainModInitializer {
		public void OnInitializeMain(MainModCoreAPI api) { }

		public void OnDisposeMain() { }
	}
}

using Nox.CCK.Mods.Cores;
using Nox.CCK.Mods.Initializers;
using UnityEngine;

namespace api.nox.websocket {
	public class Main : IMainModInitializer {
		private WebSocketServerManager _serverManager;

		public void OnInitializeMain(MainModCoreAPI api) {
			// Create WebSocket server manager
			var serverObject = new GameObject("WebSocketServerManager");
			_serverManager = serverObject.AddComponent<WebSocketServerManager>();
			Object.DontDestroyOnLoad(serverObject);

			// Subscribe to events
			_serverManager.OnClientConnected += OnClientConnected;
			_serverManager.OnClientDisconnected += OnClientDisconnected;
			_serverManager.OnMessageReceived += OnMessageReceived;

			Debug.Log("WebSocket module initialized");
		}

		private void OnClientConnected(WebSocketClient client) {
			Debug.Log($"[WebSocket] Client connected: {client.Id} from {client.RemoteEndpoint}");
		}

		private void OnClientDisconnected(WebSocketClient client) {
			Debug.Log($"[WebSocket] Client disconnected: {client.Id}");
		}

		private void OnMessageReceived(WebSocketClient client, string message) {
			Debug.Log($"[WebSocket] Message from {client.Id}: {message}");
		}

		public void OnDisposeMain() {
			if (_serverManager != null) {
				_serverManager.OnClientConnected -= OnClientConnected;
				_serverManager.OnClientDisconnected -= OnClientDisconnected;
				_serverManager.OnMessageReceived -= OnMessageReceived;

				_serverManager.StopServer();
				Object.Destroy(_serverManager.gameObject);
			}

			Debug.Log("WebSocket module disposed");
		}
	}
}

using System;

namespace api.nox.websocket {
	/// <summary>
	/// Message types for WebSocket communication
	/// </summary>
	public enum MessageType {
		Text,
		Binary,
		Ping,
		Pong,
		Close
	}

	/// <summary>
	/// WebSocket message data
	/// </summary>
	public class WebSocketMessage {
		public MessageType Type { get; set; }
		public string TextData { get; set; }
		public byte[] BinaryData { get; set; }
		public WebSocketClient Sender { get; set; }
		public DateTime Timestamp { get; set; }

		public WebSocketMessage() {
			Timestamp = DateTime.UtcNow;
		}

		public static WebSocketMessage CreateTextMessage(string text, WebSocketClient sender = null) {
			return new WebSocketMessage {
				Type = MessageType.Text,
				TextData = text,
				Sender = sender
			};
		}

		public static WebSocketMessage CreateBinaryMessage(byte[] data, WebSocketClient sender = null) {
			return new WebSocketMessage {
				Type = MessageType.Binary,
				BinaryData = data,
				Sender = sender
			};
		}
	}
}
